237	export class CognitiveImmunologyEmergency {
238	    
239	    private config: ImmunologyConfig;
240	    private threatHistory: ForeignDirectiveReport[] = [];
241	    private agentHistory: AgentModification[] = [];
242	    private sovereignRoot: string;
243	    
244	    constructor(config: Partial<ImmunologyConfig> = {}) {
245	        this.sovereignRoot = getSovereignRoot();
246	        this.config = {
247	            lockdownOnCritical: true,
248	            alertViaVoice: true,
249	            logToCloud: false,
250	            maxThreatHistory: 1000,
251	            sovereignAuthors: SOVEREIGN_AUTHORS,
252	            coreFiles: CORE_FILES,
253	            autoApproveOwnCleanup: true,
254	            ...config,
255	        };
