454	    private async isSovereignFile(filePath: string): Promise<boolean> {
455	        try {
456	            const gitAuthors = await this.getGitAuthors(filePath);
457	            const isSovereign = gitAuthors.some(a => 
458	                this.config.sovereignAuthors.some(sa => 
459	                    a.toLowerCase().includes(sa.toLowerCase())
460	                )
461	            );
462	            return isSovereign;
463	        } catch {
464	            return this.checkAuthorizationLog(filePath);
465	        }
466	    }
467	    
468	    private async getGitAuthors(filePath: string): Promise<string[]> {
469	        try {
470	            // PATCH 3: Check only the MOST RECENT commit to prevent "Touched Once, Trusted Forever"
471	            const result = await execAsync(
472	                `git log -1 --format="%an <%ae>" -- "${filePath}"`,
473	                { cwd: this.sovereignRoot }
474	            );
475	            return result.stdout.trim().split('\n').filter(Boolean);
476	        } catch {
477	            return [];
478	        }
479	    }
480	    
481	    private checkAuthorizationLog(filePath: string): boolean {
482	        const logPath = join(this.sovereignRoot, '.sovereign', 'authorization_log.json');
483	        if (!existsSync(logPath)) return false;
484	        
485	        try {
486	            const log = JSON.parse(readFileSync(logPath, 'utf-8'));
487	            return log.some((entry: any) => 
488	                entry.file === filePath &&
489	                entry.authorizedBy === 'Kbro1989' &&
490	                entry.timestamp > Date.now() - 86400000
491	            );
492	        } catch {
493	            return false;
494	        }
495	    }
