497	    // =================================================================
498	    // AGENT CHAIN TRACING
499	    // =================================================================
500	    
501	    private async traceAgentChain(filePath?: string): Promise<AgentType[]> {
502	        if (!filePath) return ['unknown'];
503	        
504	        const chain: AgentType[] = [];
505	        
506	        // PATCH 4: Read agentHistory first, as uncommitted changes reside here
507	        const fileMods = this.agentHistory.filter(m => m.file === filePath);
508	        fileMods.forEach(m => {
509	            if (!chain.includes(m.agent)) chain.push(m.agent);
510	        });
511	
512	        try {
513	            const log = await execAsync(
514	                `git log --format="%B" -- "${filePath}"`,
515	                { cwd: this.sovereignRoot }
516	            );
517	            const commits = log.stdout.toLowerCase();
518	            
519	            if (commits.includes('claude') && !chain.includes('claude')) chain.push('claude');
520	            if (commits.includes('antigravity') && !chain.includes('antigravity')) chain.push('antigravity');
521	            if (commits.includes('kimi') && !chain.includes('kimi')) chain.push('kimi');
522	            if (commits.includes('flash') && !chain.includes('flash')) chain.push('flash');
523	            
524	            const userCommits = await execAsync(
525	                `git log --format="%an" -- "${filePath}"`,
526	                { cwd: this.sovereignRoot }
527	            );
528	            if (userCommits.stdout.trim().length > 0 && !chain.includes('user')) chain.push('user');
529	            
530	        } catch {
531	            // No git history
532	        }
533	        
534	        return chain.length > 0 ? chain : ['unknown'];
535	    }
