1319			},
1320			write(s, v) {
1321				if (v == -1) { s.buffer.writeUint16BE(0x7fff, s.scan); s.scan += 2; }
1322				else if (v < 0x8000) { s.buffer.writeUInt16BE(v, s.scan); s.scan += 2; }
1323				else { s.buffer.writeUint32BE((v | 0x80000000) >>> 0, s.scan); s.scan += 4; }
1324			},
1325			min: -1, max: 2 ** 31 - 1
1326		},
1327		varint: {
