1329				checkBounds(s, 2);
1330				const firstWord = s.buffer.readUInt16BE(s.scan);
1331				s.scan += 2;
1332				if ((firstWord & 0x8000) == 0) { return (firstWord << (32 - 15)) >> (32 - 15); }
1333				checkBounds(s, 2);
1334				const secondWord = s.buffer.readUInt16BE(s.scan);
1335				s.scan += 2;
