26	 * ServiceDiscovery - Audits and reports the status of all CNS substrates.
27	 */
28	export class ServiceDiscovery {
29	    private isRunning = false;
30	    private auditTimer?: NodeJS.Timeout | undefined;
31	
32	    constructor(private readonly config: SovereignConfig) { }
33	
34	    /**
35	     * Start the audit loop with a given interval
36	     */
37	    startAuditLoop(intervalMs = 30000): void {
38	        if (this.isRunning) return;
39	        this.isRunning = true;
40	
41	        const run = async () => {
42	            if (!this.isRunning) return;
43	            try {
44	                await this.auditAll();
45	            } catch (err) {
46	                // Silent fail during shutdown
47	            }
48	            if (this.isRunning) {
49	                this.auditTimer = setTimeout(run, intervalMs);
50	            }
51	        };
52	
53	        run();
54	    }
55	
56	    /**
57	     * Stop all ongoing audits and prevent new ones from starting
58	     */
59	    stop(): void {
60	        this.isRunning = false;
61	        if (this.auditTimer) {
62	            clearTimeout(this.auditTimer);
63	            this.auditTimer = undefined;
64	        }
65	    }
66	
67	    async auditAll(): Promise<ServiceStatus[]> {
68	        // Guard: Don't run if stopped
69	        if (!this.isRunning) return [];
70	
71	        const results: ServiceStatus[] = [];
72	
73	        // 1. Audit APIs
74	        results.push(this.withHealth(await this.checkGoogleServices()));
75	        results.push(this.withHealth(await this.checkOllama()));
76	
77	        // Guard between checks
78	        if (!this.isRunning) return results;
79	
80	        // 2. Audit Extensions (GCloud SDKs)
81	        const extensions = await this.checkCloudExtensions();
82	        if (!this.isRunning) return results;
83	        results.push(...extensions.map(ext => this.withHealth(ext)));
84	
85	        // 3. Audit MCP Servers
86	        results.push(this.withHealth(await this.checkMCPServers()));
87	        if (!this.isRunning) return results;
88	
89	        // 4. Audit Knowledge Limbs (Phase 20)
90	        results.push(this.withHealth(await this.checkKnowledgeLimbs()));
91	        if (!this.isRunning) return results;
92	
93	        // 5. Audit Endpoints (Sovereign Substrate)
94	        results.push(this.withHealth(await this.checkVSCodeExtension()));
95	        if (!this.isRunning) return results;
96	
97	        results.push(this.withHealth(await this.checkCloudflareWorker()));
98	        if (!this.isRunning) return results;
99	
100	        results.push(this.withHealth(await this.checkRSCServer()));
101	        if (!this.isRunning) return results;
102	
103	        results.push(this.withHealth(await this.checkGhostLimb()));
104	        if (!this.isRunning) return results;
105	
106	        // 6. Audit System Substrate (Sovereign Root)
107	        results.push(this.withHealth(await this.checkSovereignSubstrate()));
108	        if (!this.isRunning) return results;
109	
110	        // 7. Audit Shell Tools (Git/PowerShell)
111	        const shellTools = await this.checkShellTools();
112	        if (!this.isRunning) return results;
113	        results.push(...shellTools.map(t => this.withHealth(t)));
114	
115	        return results;
116	    }
