118	    private isServiceAuthorized(id: string): HealthStatus {
119	        const lowerId = id.toLowerCase();
120	        const isAuthorized = (this.config.enabledServices as string[] ?? []).some((s: string) => s.toLowerCase() === lowerId);
121	        return isAuthorized ? HealthStatus.Ready : HealthStatus.Critical;
122	    }
