129	    private async checkGoogleServices(): Promise<Omit<ServiceStatus, 'health'>> {
130	        if (!this.isRunning) return { id: 'google_services', name: 'Google Cloud Services', status: 'INACTIVE', type: 'API', details: 'Audit stopped' };
131	
132	        const apiKey = process.env['GOOGLE_API_KEY'] || this.config.secondaryCloudApiKey;
133	
134	        if (!apiKey) {
135	            return { id: 'google_services', name: 'Google Cloud Services', status: 'INACTIVE', type: 'API', details: 'No API key in .env or config' };
136	        }
137	
138	        try {
139	            const { GoogleServices } = await import('../services/GoogleServices.js');
140	            const google = new GoogleServices({ apiKey });
141	            const audit = await google.auditAbilities();
142	            if (audit.ok && audit.value) {
143	                return {
144	                    id: 'google_services',
145	                    name: 'Google Cloud Services',
146	                    status: 'ACTIVE',
147	                    type: 'API',
148	                    details: `Abilities: ${audit.value.services.join(', ')}`
149	                };
150	            }
151	            return { id: 'google_services', name: 'Google Cloud Services', status: 'ERROR', type: 'API', details: audit.error?.message || 'Unknown error' };
152	        } catch (e) {
153	            return { id: 'google_services', name: 'Google Cloud Services', status: 'ERROR', type: 'API', details: (e as Error).message };
