301	    private async checkCloudflareWorker(): Promise<Omit<ServiceStatus, 'health'>> {
302	        if (!this.isRunning) return { id: 'worker', name: 'POG Sovereign Worker', status: 'INACTIVE', type: 'WORKER', details: 'Audit stopped' };
303	
304	        const workerUrl = process.env['CLOUDFLARE_WORKER_URL'];
