310	                if (res.ok) {
311	                    const data = await res.json() as { service?: string; status?: string };
312	                    return {
313	                        id: 'worker',
314	                        name: 'POG Sovereign Worker',
315	                        status: 'ACTIVE',
316	                        type: 'WORKER',
317	                        details: `Substrate: ${data.service || 'Online'} (${data.status || 'Verified'})`
