320	                return {
321	                    id: 'worker',
322	                    name: 'POG Sovereign Worker',
323	                    status: 'ERROR',
324	                    type: 'WORKER',
325	                    details: `HTTP ${res.status}: ${res.statusText}`
326	                };
327	            } catch (err) {
328	                return {
329	                    id: 'worker',
330	                    name: 'POG Sovereign Worker',
331	                    status: 'ERROR',
332	                    type: 'WORKER',
333	                    details: `Unreachable: ${(err as Error).message}`
334	                };
335	            }
336	        }
337	
338	        // Fallback: Check API credentials if no URL is set
339	        const cf = new CloudflareServices({
340	            accountId: (process.env['CLOUDFLARE_ACCOUNT_ID'] || this.config.cloudflareAccountId),
341	            apiToken: (process.env['CLOUDFLARE_API_TOKEN'] || this.config.cloudflareApiToken)
342	        } as CloudflareConfig);
343	
344	        const audit = await cf.auditAbilities();
345	        const accountId = cf.getAccountId();
346	
