358	    private async checkRSCServer(): Promise<Omit<ServiceStatus, 'health'>> {
359	        if (!this.isRunning) return { id: 'rsc_server', name: 'RSC Game Server', status: 'INACTIVE', type: 'EXTENSION', details: 'Audit stopped' };
360	
361	        const portDefault = 43594;
362	        const portCabbage = 43595;
363	
364	        // Helper to check a port
365	        const checkPort = async (port: number): Promise<boolean> => {
366	            if (!this.isRunning) return false;
367	            try {
368	                const { createConnection } = await import('net');
369	                return await new Promise<boolean>((resolve) => {
370	                    const socket = createConnection({ port, host: 'localhost' }, () => {
371	                        socket.end();
372	                        resolve(true);
373	                    });
374	                    socket.on('error', () => resolve(false));
375	                    socket.setTimeout(300, () => { // Faster timeout for boot
376	                        socket.destroy();
377	                        resolve(false);
