468	                name: 'Wrangler CLI',
469	                status: wranglerVersion ? 'ACTIVE' : 'INACTIVE',
470	                type: 'EXTENSION',
471	                details: wranglerVersion ? `Version: ${wranglerVersion}` : 'Wrangler not found (Try `npm i -g wrangler`)'
472	            },
473	            {
474	                id: 'tool_gcloud',
475	                name: 'Google Cloud CLI',
476	                status: gcloudVersion ? 'ACTIVE' : 'INACTIVE',
477	                type: 'EXTENSION',
478	                details: gcloudVersion ? `Installed` : 'GCloud SDK not found'
479	            }
480	        ];
481	    }
482	}
