504	     */
505	    public plotPath(
506	        targetX: number, 
507	        targetY: number, 
508	        pathfinder: DirectionalPathfinder,
509	        context: any, // GameState
510	        collisionMatrix?: Map<string, any>
511	    ): boolean {
512	        const start = this.coord;
513	        const end = { x: targetX, y: targetY, plane: this.coord.plane };
514	        
515	        try {
516	            const isPlayer = true; // For now, SovereignAvatars behave as players
517	            const path = pathfinder.findPath(start, end, context, isPlayer);
518	            if (path && path.length > 0) {
519	                if (path[0].x === this.coord.x && path[0].y === this.coord.y) {
520	                    path.shift();
521	                }
522	                this.currentPath = path;
523	                return true;
524	            } else if (path && path.length === 0) {
525	                // Already there.
526	                this.currentPath = [];
527	                return true;
528	            }
529	        } catch (error) {
530	            console.error('Failed to plot path:', error);
531	        }
532	        return false;
533	    }
