535	    /**
536	     * To be called every 600ms by the GameplaySovereigntyLimb.
537	     * Processes movement along currentPath.
538	     */
539	    public processTick() {
540	        if (this.lockTicks > 0) {
541	            this.lockTicks--;
542	            return;
543	        }
544	
545	        if (this.currentPath && this.currentPath.length > 0) {
546	            const nextStep = this.currentPath.shift()!;
547	            this.coord = { x: nextStep.x, y: nextStep.y, plane: this.coord.plane };
548	            this.x = this.coord.x;
549	            this.y = this.coord.y;
550	            this.plane = this.coord.plane;
551	            
552	            if (this.currentPath.length === 0) {
553	                this.currentPath = null;
554	                // Pending interaction evaluation happens securely in the SimulationHarness
555	            }
556	        }
557	    }
