566	    public isBusy(): boolean {
567	        return this.lockTicks > 0;
568	    }
569	
570	    /**
571	     * subscribe - Register for specific state change events (e.g., 'teleport', 'equipment_swap')
572	     */
573	    public subscribe(type: string, callback: (delta: any) => void): () => void {
574	        if (!this.subscribers.has(type)) {
575	            this.subscribers.set(type, new Set());
576	        }
577	        this.subscribers.get(type)!.add(callback);
578	        return () => this.subscribers.get(type)!.delete(callback);
579	    }
580	
581	    /**
582	     * emit - Internal helper to notify subscribers and the global callback.
583	     */
584	    public emit(type: string, delta: any) {
585	        if (this.onStateChange) {
586	            this.onStateChange(type, delta);
587	        }
588	        const set = this.subscribers.get(type);
589	        if (set) {
590	            set.forEach(cb => cb(delta));
591	        }
592	    }
593	}
