4	/**
5	 * SovereignPathResolver
6	 * 
7	 * Enforces the "D-drive First" authority rule for cache fragments and atlas data.
8	 * This is the primary mechanism for resolving C3 boundary disconnects.
9	 */
10	export class SovereignPathResolver {
11	    private static AUTHORITATIVE_ROOT = "D:\\sovereign";
12	    private static LOCAL_ROOT = "c:\\Users\\Destiny\\Desktop\\pog-vibe-interactive\\files";
13	
14	    /**
15	     * Resolves a relative path (e.g. 'atlas/spatial/m_55_50_logic.json') 
16	     * to the most authoritative existing local path.
17	     */
18	    static resolveauthoritativePath(relativePath: string): string {
19	        // Normalize the relative path to use platform-specific separators
20	        const normalizedRel = relativePath.split(/[\\\/]/).join(path.sep);
21	
22	        // 1. Check authoritative D-drive first
23	        const dPath = path.join(this.AUTHORITATIVE_ROOT, normalizedRel);
24	        if (fs.existsSync(dPath)) {
25	            return dPath;
26	        }
27	
28	        // 2. Fallback to local C-drive (the repo's own data)
29	        const cPath = path.join(this.LOCAL_ROOT, normalizedRel);
30	        return cPath; 
31	    }
32	
33	    /**
34	     * Helper for specifically resolving refilled logic fragments.
35	     */
36	    static resolveLogicFragment(major: number, id: number): string {
37	        const rel = path.join("refilled", `js5-${major}`, `${id}_logic.json`);
38	        return this.resolveauthoritativePath(rel);
39	    }
40	    
41	    /**
42	     * Helper for spatial atlas anchors.
43	     */
44	    static resolveSpatialAnchor(coordKey: string): string {
45	        const rel = path.join("atlas", "spatial", `${coordKey}_logic.json`);
46	        return this.resolveauthoritativePath(rel);
47	    }
48	}
