12	/**
13	 * SpaceRegistry - Phase C1: Deterministic Region-to-Space Mapping.
14	 * 
15	 * Provides the "Expected Space ID" for any given coordinate, allowing 
16	 * the FragmentOrchestrator to load the correct logic substrate.
17	 */
18	export class SpaceRegistry {
19	    private static instance: SpaceRegistry;
20	    private registry: Map<number, SpaceMetadata> = new Map();
21	
22	    private constructor() {
23	        this.initializeKnownSpaces();
24	    }
25	
26	    public static getInstance(): SpaceRegistry {
27	        if (!SpaceRegistry.instance) {
28	            SpaceRegistry.instance = new SpaceRegistry();
29	        }
30	        return SpaceRegistry.instance;
31	    }
32	
33	    private initializeKnownSpaces(): void {
34	        // Core regional anchors (Phase C1 initial set)
35	        
36	        // Barrows: Mapsquare (55, 51) -> RegionID (55 << 8 | 51) = 14131
37	        this.addSpace(55, 51, 'barrows', 'Barrows Crypt');
38	        
39	        // Neighbor of Barrows (South): (55, 50) -> 14130
40	        this.addSpace(55, 50, 'm_55_50', 'Barrows South Corridor');
41	
42	        // Prifddinas: Mapsquare (33, 51) -> RegionID (33 << 8 | 51) = 8501
43	        this.addSpace(33, 51, 'prifddinas', 'Prifddinas Lodestone');
44	
45	        // Additional common regions for Global Discovery (C2/C3)
46	        this.addSpace(50, 50, 'lumbridge', 'Lumbridge');
47	        this.addSpace(51, 53, 'varrock', 'Varrock Center');
48	        this.addSpace(46, 54, 'falador', 'Falador');
49	        this.addSpace(38, 54, 'ardougne', 'Ardougne');
50	    }
51	
52	    private addSpace(mx: number, my: number, spaceId: string, name: string): void {
53	        const regionId = (mx << 8) | my;
54	        this.registry.set(regionId, {
55	            regionId,
56	            spaceId,
57	            name,
58	            mapsquare: { x: mx, y: my }
59	        });
60	    }
61	
62	    /**
63	     * getSpaceForCoords - Deterministically maps world coords to a Space ID.
64	     */
65	    public getSpaceForCoords(x: number, y: number): SpaceMetadata | null {
66	        const mx = x >> 6;
67	        const my = y >> 6;
68	        const regionId = (mx << 8) | my;
69	        
70	        const metadata = this.registry.get(regionId);
71	        if (metadata) return metadata;
72	
73	        // Default: Return a generic coordinate-based space ID
74	        return {
75	            regionId,
76	            spaceId: `m_${mx}_${my}`,
77	            name: `Mapsquare (${mx}, ${my})`,
78	            mapsquare: { x: mx, y: my }
79	        };
80	    }
81	
82	    /**
83	     * getRegionName - Logic-naming helper for FragmentOrchestrator.
84	     */
85	    public getRegionName(mx: number, my: number): string {
86	        const regionId = (mx << 8) | my;
87	        const metadata = this.registry.get(regionId);
88	        return metadata ? metadata.spaceId : `m_${mx}_${my}`;
89	    }
90	
91	    /**
92	     * getRegionID - Standard Jagex RegionID calculation.
93	     */
94	    public static getRegionID(x: number, y: number): number {
95	        return ((x >> 6) << 8) | (y >> 6);
96	    }
97	}
