10	export interface ScreenCoord {
11	    u: number; // horizontal pixel/grid
12	    v: number; // vertical pixel/grid
13	}
14	
15	export interface Region {
16	    id: string;
17	    base: WorldCoord; // origin of region
18	    size: { width: number; height: number };
19	}
20	
21	export interface CameraState {
22	    originX: number;
23	    originY: number;
24	    zoom: number; // optional scale factor
25	}
26	
27	export class SpatialTransform {
28	    private static REGION_SIZE = 64; // Authoritative NXT mapsquare stride
29	
30	    // Absolute world â†’ region + local offset
31	    public static worldToRegion(pos: WorldCoord): { regionId: string; localOffset: { dx: number; dy: number; dz: number } } {
32	        const regionX = Math.floor(pos.x / this.REGION_SIZE);
33	        const regionY = Math.floor(pos.y / this.REGION_SIZE);
34	        
35	        const regionId = `${regionX}_${regionY}`;
36	        const dx = pos.x % this.REGION_SIZE;
37	        const dy = pos.y % this.REGION_SIZE;
38	        
39	        return {
40	            regionId,
41	            localOffset: { dx, dy, dz: pos.z }
42	        };
43	    }
44	
45	    // Region + local offset â†’ world coordinates
46	    public static regionToWorld(regionId: string, offset: { dx: number; dy: number; dz: number }): WorldCoord {
47	        const [rx, ry] = regionId.split('_').map(Number);
48	        
49	        return {
50	            x: (rx * this.REGION_SIZE) + offset.dx,
51	            y: (ry * this.REGION_SIZE) + offset.dy,
52	            z: offset.dz
53	        };
54	    }
55	
56	    // World â†’ screen / vision grid
57	    public static worldToScreen(pos: WorldCoord, camera: CameraState): ScreenCoord {
58	        return {
59	            u: (pos.x - camera.originX) * camera.zoom,
60	            v: (pos.y - camera.originY) * camera.zoom - (pos.z * 10) // Basic z-height offset logic
61	        };
62	    }
63	
64	    // Screen â†’ world
65	    public static screenToWorld(screen: ScreenCoord, camera: CameraState, baseZ: number = 0): WorldCoord {
66	        return {
67	            x: Math.round((screen.u / camera.zoom) + camera.originX),
68	            y: Math.round(((screen.v + (baseZ * 10)) / camera.zoom) + camera.originY),
69	            z: baseZ
70	        };
71	    }
72	
73	    // Tick-level invariant assertion
74	    public static validateInvariant(pos: WorldCoord): boolean {
75	        const { regionId, localOffset } = this.worldToRegion(pos);
76	        const recon = this.regionToWorld(regionId, localOffset);
77	        
78	        if (pos.x === recon.x && pos.y === recon.y && pos.z === recon.z) {
79	            return true;
80	        }
81	        logger.error({ original: pos, reconstructed: recon }, 'Invariant Transform Failure: Spatial Desync!');
82	        return false;
83	    }
84	}
